MOTIVE.forEach((m) => { if (M2[m.id]) { m.svg = M2[m.id]; m.fertig = true; } });
function motivSeite() {
  return `<div class="mv"><a class="zurueck" href="#s=eltern&g=${P.g}">‹ Adventskalender</a><h1 style="font-size:24px;color:var(--accent)">Motiv-Vorrat</h1><p class="unter">16 Motive, alle selbst gezeichnet (SVG in der App, kein Netz, keine Fotos), dazu 3 Sonder-Motive (Krampus, Tür 6, Tür 24). Alle in einem Stil ausgearbeitet. Die Eltern wählen je Tür ein Motiv und schreiben einen Satz dazu – oder nehmen den Vorschlags-Satz.</p>
    <div class="mv-gitter">${MOTIVE.map((m) => `<div class="mv-k"><div class="bild">${m.svg('w' + (++MZ))}</div><div class="txt"><b>${esc(m.name)}</b><small>„${esc(m.satz)}“</small><span class="tag ${m.fertig ? '' : 's'}">${m.fertig ? m.gruppe : 'Skizze · ' + m.gruppe}</span></div></div>`).join('')}</div></div>`;
}
